import {DEMO_CONTAINERS,CONFIDENCE,fillStatus,optimizeRoute,selectStops,aqiLabel,num,getContainerDataState} from './data.js';
import {icon,hydrateIcons} from './icons.js';
import {mountMap,destroyMap} from './map.js';
import {dataNotice} from './provenance.js';
const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}};
const saved=storage.get('ecomind-v1',{});
const state={page:'overview',filter:'all',search:'',containers:Array.isArray(saved.containers)&&saved.containers.length?saved.containers:structuredClone(DEMO_CONTAINERS),settings:{name:'Зелёный квартал',city:'Астана, Казахстан',latitude:51.1327,longitude:71.4249,fuel:22,factor:1.3,stopMinutes:3,apiBase:'',...saved.settings},route:{policy:'current',threshold:75,horizon:12},air:null,airError:'',airLoading:false,analysisAvailable:false};
function persist(){if(!storage.set('ecomind-v1',{containers:state.containers,settings:state.settings}))toast('Браузер не смог сохранить изменения. Скачайте отчёт.','warning');}
function criticalCount(){return state.containers.filter(c=>c.fill>=75).length;}
function currentRoute(){return optimizeRoute(selectStops(state.containers,state.route.policy,state.route.threshold,state.route.horizon));}
const pageTitles={overview:'Обзор',map:'Карта Астаны',containers:'Контейнеры',routes:'Маршруты',air:'Качество воздуха',analytics:'Аналитика',settings:'Настройки'};
function today(){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date());}
$('#top-date').textContent=today();hydrateIcons();
function heading(title,description,eyebrow='ВАШ КВАРТАЛ. ПОД КОНТРОЛЕМ.',actions=true){return `<div class="page-heading"><div><div class="eyebrow">${icon('leaf')}${eyebrow}</div><h1>${title}</h1><p class="page-description">${description}</p></div>${actions?`<div class="heading-actions"><button class="button" data-action="export">${icon('download')}Скачать отчёт</button><button class="button primary" data-action="observation">${icon('plus')}Добавить наблюдение</button></div>`:''}</div>`;}
function demoNote(){const status=getContainerDataState(state.containers);return '<div class="demo-note">'+icon('info')+'<span>Карта Астаны — OpenStreetMap. Данные воздуха — открытая модель CAMS / Open-Meteo. '+(status.hasDemo?'В контейнерах и показателях ещё есть выдуманные данные. ':'')+'Ручные наблюдения сохраняются в этом браузере.</span></div>';}
function stat(title,value,unit,ico,footer,warn=false){return `<div class="stat-card ${warn?'warn':''}"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-bottom"><span>${footer}</span></div></div>`;}
function stats(){
 const known=state.containers.filter(c=>Number.isFinite(c.fill)),avg=known.length?known.reduce((sum,c)=>sum+c.fill,0)/known.length:null;
 const status=getContainerDataState(state.containers),demoLabel=status.hasDemo?'Выдуманные данные / примеры':'По реальным наблюдениям';
 return `<div class="stats-grid">${stat('Контейнеров в квартале',state.containers.length,'','bin',demoLabel)}${stat('Требуют внимания',criticalCount(),'','warning',demoLabel,true)}${stat('Средняя заполненность',num(avg),'%','chart',demoLabel)}${stat('Качество воздуха',num(state.air?.current?.european_aqi),'AQI','wind',state.air?'Open-Meteo · '+aqiLabel(state.air.current.european_aqi):state.airLoading?'Получаем данные…':'Нет текущих данных')}</div>`;
}
function mapPanel(full=false,layer='waste'){
 return `<section class="panel map-panel ${full?'full-map':''}" id="city-map"><div class="panel-head"><div><h2 class="panel-title">${icon('map')}Карта Астаны</h2><p class="panel-subtitle">Настоящие улицы и здания · OpenStreetMap</p></div><div class="panel-head-actions"><span class="badge green"><i></i>Настоящая карта</span><button class="icon-button" data-map-action="fullscreen" aria-label="Развернуть карту">${icon('maximize')}</button></div></div>${dataNotice(state.containers,'map')}<div class="map-viewport"><div class="map-canvas"></div><div class="map-top"><div class="map-chips"><button class="map-chip ${layer==='waste'?'active':''}" data-map-action="waste">${icon('bin')}Контейнеры</button><button class="map-chip ${layer==='air'?'active':''}" data-map-action="air">${icon('wind')}Воздух</button><button class="map-chip ${layer==='route'?'active':''}" data-map-action="route">${icon('route')}Маршрут</button></div><span class="map-location">${icon('pin')}Астана, Казахстан</span></div><div class="map-controls"><button data-map-action="city" title="Показать Астану целиком" aria-label="Показать Астану целиком">${icon('map')}</button><button data-map-action="zoom-in" aria-label="Приблизить">${icon('plus')}</button><button data-map-action="zoom-out" aria-label="Отдалить">${icon('minus')}</button><button data-map-action="center" title="Показать участок с контейнерами" aria-label="Показать участок с контейнерами">${icon('locate')}</button><button data-map-action="3d" aria-pressed="false" aria-label="Переключить 2D и 3D"><strong style="font-size:9px">3D</strong></button></div><div class="map-legend"><span class="legend-item"><i class="legend-dot" style="background:#329b6b"></i>В норме</span><span class="legend-item"><i class="legend-dot" style="background:#db9b3d"></i>Скоро вывоз</span><span class="legend-item"><i class="legend-dot" style="background:#df6957"></i>Срочный вывоз</span></div><div class="map-caption">Астана · OpenStreetMap</div></div><div class="map-footer"><span>${icon('locate')}<strong>${state.containers.length} контейнеров</strong> · ${getContainerDataState(state.containers).hasDemo?'точки пока условные':'подтверждённые площадки'}</span><a href="#map" class="text-button">${full?'Нажмите на точку':'Открыть карту'}${icon(full?'info':'arrow-up-right')}</a></div></section>`;
}
function airChart(big=false){
 const data=state.air?.chart??[];if(!data.length)return '<div class="empty-chart">Модельный прогноз появится после загрузки</div>';
 const w=big?760:250,h=big?200:65,max=Math.max(20,...data.map(d=>d.value)),min=0;
 const coords=data.map((d,i)=>[i/(data.length-1||1)*w,h-8-(d.value-min)/(max-min)*(h-20)]);
 const line=coords.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
 return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Модельный прогноз европейского AQI на следующие 24 часа"><defs><linearGradient id="air-gradient-${big}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b3d19a" stop-opacity=".35"/><stop offset="1" stop-color="#d5e4c6" stop-opacity=".05"/></linearGradient></defs>${[.25,.5,.75].map(y=>`<path d="M0 ${h*y}H${w}" stroke="#edf1e6" stroke-width="1" stroke-dasharray="4 4"/>`).join('')}<path d="${line}L${w},${h}H0Z" fill="url(#air-gradient-${big})"/><path d="${line}" stroke="#9fbc82" stroke-width="${big?2.3:1.5}" fill="none" stroke-linejoin="round"/></svg>`;
}
function airLabels(){const data=state.air?.chart??[];return `<div class="chart-labels">${[0,6,12,18,23].map(i=>`<span>${data[i]?.time?.slice(11,16)??'—'}</span>`).join('')}</div>`;}
function airPanel(){const c=state.air?.current;return `<section class="panel air-panel"><div class="panel-head"><h2 class="panel-title">${icon('wind')}Дышите спокойнее</h2><a href="#air" class="icon-button" aria-label="Подробнее о воздухе">${icon('arrow-up-right')}</a></div><div class="air-number-line"><div class="air-number">${num(c?.european_aqi)}<small>Европейский индекс AQI</small></div><span class="air-state ${state.airError?'error':''}">${c?aqiLabel(c.european_aqi):state.airLoading?'Загрузка…':'Нет данных'}</span></div><div class="air-scale-wrap"><div class="air-scale"><span style="background:#a9c894"></span><span style="background:#c6d49a"></span><span style="background:#e6d297"></span><span style="background:#e7b49a"></span><span style="background:#dca3a3"></span><span style="background:#bea6ba"></span></div><div class="air-scale-labels"><span>0 · Хорошее</span><span>100+ · Очень плохое</span></div></div><div class="air-metrics"><div><span>PM2.5</span><strong>${num(c?.pm2_5,1)} <small>мкг/м³</small></strong></div><div><span>PM10</span><strong>${num(c?.pm10,1)} <small>мкг/м³</small></strong></div></div><div class="air-chart-wrap"><div class="air-chart">${airChart()}</div>${airLabels()}</div><div class="air-source">${icon('info')}<span>${state.airError?'Источник временно недоступен':`Open-Meteo · CAMS${state.air?' · '+esc(state.air.current.time?.slice(11,16)??''):''}`} · <a href="#air">подробнее</a></span></div></section>`;}
function recommendation(){return `<section class="recommendation"><div class="recommend-title">${icon('sparkles')}Подсказка EcoMind</div>${getContainerDataState(state.containers).hasDemo?'<span class="badge orange" style="margin-top:10px">По выдуманным данным</span>':''}<h3>${criticalCount()?`${criticalCount()} контейнера —<br>в приоритет на вывоз.`:'Всё спокойно.<br>Квартал под заботой.'}</h3><p>${criticalCount()?'В демонстрационном наборе они заполнены от 75%. Сравните порядок остановок и спланируйте следующий рейс.':'Текущие оценки ниже порога вывоза. Продолжайте наблюдения и проверяйте динамику.'}</p><a href="#routes" class="button">Спланировать маршрут ${icon('arrow-right')}</a></section>`;}
function filteredContainers(){return state.containers.filter(c=>(state.filter==='all'||(state.filter==='attention'?c.fill>=75:c.fill<75))&&`${c.id} ${c.name} ${c.address}`.toLocaleLowerCase('ru').includes(state.search.toLocaleLowerCase('ru')));}
function tableRows(limit=Infinity){return filteredContainers().slice(0,limit).map(c=>{const s=fillStatus(c.fill);return `<tr class="table-row" tabindex="0" role="button" data-container="${esc(c.id)}" aria-label="Открыть ${esc(c.id)}"><td><div class="container-cell"><span class="bin-icon">${icon(c.type==='Переработка'?'recycle':'bin')}</span><div class="cell-name">${esc(c.name)}<div class="cell-id">${esc(c.id)} · ${c.source==='manual'?'Ручное наблюдение':c.source==='gemini'?'Анализ фото':'Демо'}</div></div></div></td><td><div class="fill-cell"><span class="fill-track"><span style="width:${c.fill??0}%;background:${s.color}"></span></span><strong style="color:${s.color}">${c.fill===null?'—':c.fill+'%'}</strong></div></td><td><span class="badge ${s.key==='critical'?'red':s.key==='high'?'orange':s.key==='normal'?'green':''}"><i></i>${s.label}</span></td><td><span class="confidence"><i></i>${CONFIDENCE[c.confidence]??'—'}</span></td><td style="font-size:8px;color:#9eaa97">${c.observedAt?esc(new Date(c.observedAt).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})):'Демо: '+c.ago+' мин назад'}</td><td><span style="color:#9ba994">${icon('arrow-up-right')}</span></td></tr>`;}).join('')||'<tr><td colspan="6" class="table-empty">Контейнеры не найдены. Измените фильтр или поисковый запрос.</td></tr>';}
function containerTable(full=false){const count=filteredContainers().length;return `<section class="panel table-panel" style="${full?'margin-top:0':''}"><div class="panel-head"><h2 class="panel-title">${icon('bin')}${full?'Все контейнеры':'Контейнеры под наблюдением'}</h2>${full?`<button class="text-button" data-action="export">${icon('download')}Экспорт CSV</button>`:`<a href="#containers" class="text-button">Все контейнеры ${icon('arrow-right')}</a>`}</div>${dataNotice(state.containers)}<div class="table-toolbar"><div class="tab-group"><button class="tab-button ${state.filter==='all'?'active':''}" data-filter="all">Все <span>${state.containers.length}</span></button><button class="tab-button ${state.filter==='attention'?'active':''}" data-filter="attention">Требуют внимания <span>${criticalCount()}</span></button><button class="tab-button ${state.filter==='normal'?'active':''}" data-filter="normal">В норме</button></div><label class="table-search">${icon('search')}<input type="search" id="container-search" placeholder="Найти контейнер…" value="${esc(state.search)}" aria-label="Поиск контейнера"></label></div><div class="table-wrap"><table><thead><tr><th>Контейнер / площадка</th><th>Заполненность</th><th>Статус</th><th>Уверенность оценки</th><th>Наблюдение</th><th></th></tr></thead><tbody id="container-rows">${tableRows(full?Infinity:5)}</tbody></table></div><div class="table-bottom"><span id="table-count">Показано ${Math.min(count,full?count:5)} из ${count} контейнеров</span><button class="text-button" data-action="methodology">Как рассчитывается оценка? ${icon('info')}</button></div></section>`;}
function overview(){return heading('Город под заботой.','Всё, что нужно для чистого квартала — в одном пространстве.')+stats()+`<div class="dashboard-grid"><div>${mapPanel()}${containerTable()}</div><div class="right-column">${airPanel()}${recommendation()}</div></div>`+demoNote();}
function mapPage(){return heading('Астана. На настоящей карте.','Реальные улицы и здания города. Контейнеры пока показаны для демонстрации.','КАРТА АСТАНЫ')+mapPanel(true)+demoNote();}
function containersPage(){return heading('Каждый контейнер на виду.','Следите за заполнением, добавляйте наблюдения и замечайте проблемы раньше.','WASTE MONITOR')+stats()+containerTable(true)+demoNote();}
function routesPage(){const r=currentRoute(),stops=r.points.slice(1,-1),km=r.distance*state.settings.factor,time=km/20*60+stops.length*state.settings.stopMinutes;return heading('Меньше пути. Больше пользы.','Выберите контейнеры для вывоза и сравните порядок остановок.','ROUTE PLANNER',false)+dataNotice(state.containers,'routes')+`<div class="route-layout"><div class="panel route-controls"><h3>Параметры рейса</h3><div class="field"><label for="route-policy">Какие контейнеры вывозить</label><select id="route-policy"><option value="current" ${state.route.policy==='current'?'selected':''}>По текущей заполненности</option><option value="calendar" ${state.route.policy==='calendar'?'selected':''}>Все, по календарю</option><option value="forecast" ${state.route.policy==='forecast'?'selected':''}>По сценарию заполнения</option></select></div><div class="field"><label for="route-threshold">Порог вывоза <strong id="threshold-value">${state.route.threshold}%</strong></label><input type="range" id="route-threshold" min="40" max="95" step="5" value="${state.route.threshold}" ${state.route.policy==='calendar'?'disabled':''}><small>Заполненность, при которой контейнер попадает в рейс.</small></div>${state.route.policy==='forecast'?`<div class="field"><label for="route-horizon">Горизонт сценария</label><select id="route-horizon"><option value="12" ${state.route.horizon===12?'selected':''}>Через 12 часов</option><option value="24" ${state.route.horizon===24?'selected':''}>Через 24 часа</option><option value="48" ${state.route.horizon===48?'selected':''}>Через 48 часов</option></select><small>Линейный рост по заданным демонстрационным темпам. Не обученный прогноз.</small></div>`:''}<button class="button primary wide" data-action="calculate-route">${icon('route')}Пересчитать маршрут</button><div class="route-help">Ближайший сосед + 2-opt. Сравнение использует одинаковые остановки. Маршрут схематический, без учёта дорог, ПДД и ограничений машины.</div><div class="section-heading" style="margin-top:16px"><h3 style="margin:0;font-size:11px">Остановки</h3><span class="badge green">${stops.length} точек</span></div><div class="route-stop-list">${stops.length?stops.map((c,i)=>`<button class="route-stop" data-container="${c.id}" style="width:100%;text-align:left"><span>${i+1}</span><span>${esc(c.name)}<small>${esc(c.id)}</small></span><span class="badge ${c.fill>=90?'red':'orange'}">${c.fill}%</span></button>`).join(''):'<p class="route-help">При выбранном пороге нет контейнеров для вывоза.</p>'}</div><button class="text-button" data-action="export-route" style="margin-top:18px">${icon('download')}Скачать план рейса</button></div><div>${mapPanel(true,'route')}<div class="route-summary"><div class="panel"><small>Сценарная длина</small><strong>${num(km,2)} <small>км</small></strong><small>Поправка на дороги ×${num(state.settings.factor,1)}</small></div><div class="panel"><small>Сценарное время</small><strong>${num(time)} <small>мин</small></strong><small>20 км/ч + ${state.settings.stopMinutes} мин на остановку</small></div><div class="panel"><small>Вклад порядка остановок</small><strong>${num(r.saving)}<small>%</small></strong><small>На том же наборе контейнеров</small></div></div></div></div><div class="methodology"><strong>Расчётная симуляция.</strong> Базовый порядок — последовательность точек в реестре; оптимизированный — результат алгоритма. Расстояние по прямой умножается на явно заданную поправку ${num(state.settings.factor,1)}. Это не дорожная навигация и не доказательство экономии в реальном рейсе. Поправку необходимо откалибровать по GPS.</div>`;}
function airPage(){const c=state.air?.current;return heading('Понимать воздух вокруг.','Открытые данные помогают увидеть контекст и задавать правильные вопросы.','AIR QUALITY',false)+`<div class="air-hero"><div><span class="badge green">${icon('pin')}${esc(state.settings.city)}</span><h2 style="margin-top:17px">${c?aqiLabel(c.european_aqi):state.airLoading?'Загружаем данные…':'Данные пока недоступны'}</h2><p>Модель CAMS · европейский AQI<br>${state.air?esc(c.time?.replace('T',' ')??'')+' · '+esc(state.air.timezone):'Источник: Open-Meteo'}</p></div><div class="air-number">${num(c?.european_aqi)}<small>Европейский AQI</small></div></div>${state.airError?`<div class="error-note">${icon('info')} ${esc(state.airError)} <button class="text-button" data-action="refresh-air">Повторить загрузку</button></div>`:''}<div class="metric-grid">${stat('Мелкие частицы PM2.5',num(c?.pm2_5,1),'мкг/м³','wind','Модельная концентрация')}${stat('Частицы PM10',num(c?.pm10,1),'мкг/м³','wind','Модельная концентрация')}${stat('Европейский AQI',num(c?.european_aqi),'','leaf',aqiLabel(c?.european_aqi))}${stat('Американский AQI',num(c?.us_aqi),'','chart','Отдельная шкала US AQI')}</div><section class="panel content-panel" style="margin-top:20px"><div class="section-heading"><div><h2>Что ожидает модель</h2><p style="font-size:9px">Европейский AQI · следующие 24 часа · ${esc(state.air?.timezone??'часовой пояс источника')}</p></div><button class="button" data-action="refresh-air">${icon('refresh',state.airLoading?'spin':'')}Обновить</button></div><div class="large-chart">${airChart(true)}</div>${airLabels()}</section><div class="page-grid" style="margin-top:20px"><section class="panel content-panel"><h2>В каких координатах смотрим?</h2><p>Данные относятся к модельной ячейке, ближайшей к выбранным координатам.</p><form id="air-coordinates" style="margin-top:20px"><div class="form-grid"><div class="field"><label for="air-lat">Широта</label><input id="air-lat" name="latitude" type="number" min="-90" max="90" step="any" value="${state.settings.latitude}" required></div><div class="field"><label for="air-lng">Долгота</label><input id="air-lng" name="longitude" type="number" min="-180" max="180" step="any" value="${state.settings.longitude}" required></div></div><button class="button primary" type="submit">${icon('locate')}Получить данные</button></form></section><section class="panel content-panel"><h2>Прозрачность — часть заботы</h2><p>Это результат атмосферной модели, а не показание датчика во дворе. Европейский и американский AQI используют разные шкалы. Прогноз на графике получен от открытого источника; собственная модель EcoMind ещё не обучена.</p><a class="text-button" href="https://open-meteo.com/en/docs/air-quality-api" target="_blank" rel="noopener" style="margin-top:18px">Open-Meteo · Copernicus CAMS ${icon('external')}</a></section></div><div class="methodology">Качество воздуха — контекстный модуль пилота. Эти данные сами по себе не подтверждают влияние маршрутов вывоза на воздух в районе. Для локального исследования нужны проверенные датчики и история измерений.</div>`;}
function analyticsPage(){const policies=[['calendar','По календарю'],['current','По текущей оценке'],['forecast','По сценарию +24 ч']];return heading('Проверять пользу цифрами.','Отделяем эффект выбора контейнеров от эффекта оптимизации маршрута.','СРАВНИТЕЛЬНАЯ СИМУЛЯЦИЯ · 3 × 2',false)+dataNotice(state.containers,'routes')+`<section class="panel content-panel"><div class="section-heading"><div><h2>Одинаковые остановки. Два порядка.</h2><p style="font-size:10px">Сценарный расчёт по демонстрационным данным. Порог отбора — ${state.route.threshold}%.</p></div><button class="button" data-action="export-simulation">${icon('download')}Скачать</button></div><div class="table-wrap"><table class="simulation-table"><thead><tr><th>Правило выбора контейнеров</th><th>Остановки</th><th>Базовый порядок</th><th>Оптимизированный</th><th>Изменение длины</th></tr></thead><tbody>${policies.map(([p,label],i)=>{const stops=selectStops(state.containers,p,state.route.threshold,24),r=optimizeRoute(stops);return `<tr><td>${label}<small>${['Все контейнеры в реестре','Только достигшие порога','Линейный демонстрационный рост'][i]}</small></td><td>${stops.length}</td><td>${num(r.originalDistance*state.settings.factor,2)} км</td><td><strong>${num(r.distance*state.settings.factor,2)} км</strong></td><td><span class="badge green">−${num(r.saving,1)}%</span></td></tr>`;}).join('')}</tbody></table></div></section><div class="page-grid" style="margin-top:20px"><section class="panel content-panel"><span class="connected-icon">${icon('route')}</span><h2 style="margin-top:17px">Что показывает сравнение</h2><p>Разница внутри одной строки — вклад алгоритма маршрутизации. Сравнение между строками показывает эффект отбора контейнеров. Сокращение пути нельзя оценивать отдельно от переполнений и обязательных вывозов.</p></section><section class="panel content-panel"><span class="connected-icon">${icon('database')}</span><h2 style="margin-top:17px">Чего пока недостаточно</h2><p>Нет полевых GPS-треков, истории притока отходов и путевых листов. Не рассчитываем точность прогноза или доказанную экономию. Следующий шаг — сбор наблюдений и согласованный пилот с подрядчиком.</p></section></div><section class="panel content-panel" style="margin-top:20px"><h2>От прототипа к измеримому пилоту</h2><div class="page-grid" style="margin-top:20px">${[['01','Согласовать данные','Координаты, вместимость, обязательный график и согласие подрядчика.'],['02','Наблюдать несколько недель','Фото до и после вывоза, отметки времени, GPS, остановки и жалобы.'],['03','Откалибровать симуляцию','Проверить расстояния по трекам, учесть приток и перераспределение отходов.'],['04','Проверить в реальных рейсах','Сопоставимые дни, неизменный уровень сервиса и учёт переполнений.']].map(([n,t,d])=>`<div style="display:flex;gap:15px"><span style="font-size:24px;color:#c4d4b4">${n}</span><div><h3 style="font-size:12px;color:#6f895b;margin:3px 0 7px">${t}</h3><p style="font-size:10px">${d}</p></div></div>`).join('')}</div></section><div class="methodology"><strong>Методика из PDF.</strong> Матрица 3 × 2 отдельно оценивает выбор остановок и их порядок. В этом прототипе используется единичный сценарий, а не многодневная симуляция с перерасчётом притока. Проценты в таблице не являются полевыми результатами.</div>`;}
function settingsPage(){return heading('Настроим под ваш квартал.','Параметры хранятся локально в этом браузере.','НАСТРОЙКИ ПИЛОТА',false)+`<form id="settings-form" class="settings-content"><section class="panel"><h2 class="panel-title">${icon('building')}Ваше пространство</h2><div class="setting-row"><div><h3>Название квартала</h3><p>Отображается в навигации и на карте.</p></div><div class="field"><input name="name" aria-label="Название квартала" maxlength="50" value="${esc(state.settings.name)}" required></div></div><div class="setting-row"><div><h3>Город</h3><p>Подпись пространства. Координаты воздуха меняются отдельно.</p></div><div class="field"><input name="city" aria-label="Город" maxlength="70" value="${esc(state.settings.city)}" required></div></div></section><section class="panel"><h2 class="panel-title">${icon('route')}Допущения симуляции</h2><div class="setting-row"><div><h3>Поправка к расстоянию</h3><p>Умножает расстояние по прямой.<br>Требует калибровки по GPS, не учитывает ограничения дорог.</p></div><div class="field"><input name="factor" type="number" min="1" max="3" step="0.1" aria-label="Поправка к расстоянию" value="${state.settings.factor}" required></div></div><div class="setting-row"><div><h3>Время остановки, мин</h3><p>Для оценки длительности рейса. Скорость принята равной 20 км/ч.</p></div><div class="field"><input name="stopMinutes" type="number" min="1" max="30" step="1" aria-label="Время остановки" value="${state.settings.stopMinutes}" required></div></div></section><section class="panel"><h2 class="panel-title">${icon('camera')}Анализ фотографий</h2><div class="setting-row"><div><h3>${state.analysisAvailable?'Сервис анализа подключён':'Нужен ключ Gemini'}</h3><p>Фото анализируется через сервер. Ключ API хранится в серверной переменной GEMINI_API_KEY и не попадает в Git или браузер.</p></div><span class="badge ${state.analysisAvailable?'green':'orange'}">${state.analysisAvailable?'Подключён':'Не подключён'}</span></div><div class="setting-row"><div><h3>Адрес собственного сервера</h3><p>Необязательно. Для отдельного FastAPI-сервера укажите HTTPS URL.<br>Оставьте пустым для встроенного сервиса.</p></div><div class="field"><input name="apiBase" type="url" aria-label="Адрес API сервера" placeholder="https://your-api.example" value="${esc(state.settings.apiBase)}"></div></div><div class="setting-actions"><button class="button primary" type="submit">${icon('check')}Сохранить настройки</button><button type="button" class="button" data-action="check-api">${icon('refresh')}Проверить подключение</button></div></section><section class="panel"><h2 class="panel-title">${icon('database')}Данные в браузере</h2><div class="setting-row"><div><h3>Скачать перед переносом</h3><p>Наблюдения не синхронизируются между устройствами.<br>Используйте экспорт, чтобы сохранить результаты.</p></div><button type="button" class="button" data-action="export">${icon('download')}CSV</button></div><div class="setting-row" style="border-bottom:0"><div><h3>Начать демонстрацию заново</h3><p>Восстановит 12 исходных контейнеров. Настройки сохранятся.</p></div><button type="button" class="button" data-action="reset">Сбросить демо</button></div></section></form>`;}
function render({keepScroll=false}={}){
 const y=window.scrollY;destroyMap();
 $('#main').innerHTML=`<div class="page-enter">${({overview, map:mapPage, containers:containersPage, routes:routesPage,air:airPage,analytics:analyticsPage,settings:settingsPage}[state.page]||overview)()}</div>`;
 $('#breadcrumb-current').textContent=pageTitles[state.page];$('#nav-count').textContent=state.containers.length;
 document.querySelectorAll('[data-page]').forEach(el=>{const active=el.dataset.page===state.page;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('.workspace strong').textContent=state.settings.name;$('.workspace small').textContent=state.settings.city;
 if($('#city-map'))mountMap($('#city-map'),{containers:state.containers,route:currentRoute(),onSelect:showContainer,layer:state.page==='routes'?'route':'waste'});
 hydrateIcons($('#main'));if(keepScroll)window.scrollTo(0,y);
}
function navigate(){const page=location.hash.slice(1);state.page=Object.hasOwn(pageTitles,page)?page:'overview';state.filter='all';state.search='';$('#sidebar').classList.remove('open');$('.mobile-backdrop')?.classList.remove('open');closeModal();render();window.scrollTo(0,0);}
window.addEventListener('hashchange',navigate);
function toast(message,ico='check'){const el=document.createElement('div');el.className='toast';el.innerHTML=icon(ico)+`<span>${esc(message)}</span>`;$('#toast-stack').append(el);setTimeout(()=>el.remove(),5000);}
let modalReturnFocus=null;
function modal(title,body,footer='',large=false){
 closeModal();modalReturnFocus=document.activeElement;
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;
 document.body.style.overflow='hidden';$('#modal-root [data-action="close-modal"]').focus();
 $('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
}
function closeModal(){if(!$('#modal-root')?.innerHTML)return;$('#modal-root').innerHTML='';document.body.style.overflow='';modalReturnFocus?.focus?.();modalReturnFocus=null;}
document.addEventListener('keydown',e=>{
 if(e.key==='Escape')closeModal();
 if(e.key==='Tab'&&$('#modal-root').innerHTML){const list=[...$('#modal-root').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
 const row=e.target.closest('.table-row');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showContainer(row.dataset.container);}
});
function showContainer(id){const c=state.containers.find(x=>x.id===id);if(!c)return;const s=fillStatus(c.fill);modal(`${esc(c.id)} · ${esc(c.name)}`,`${dataNotice([c])}<div class="detail-fill"><div><p style="font-size:9px;margin-bottom:6px">Оценка заполненности</p><strong style="color:${s.color}">${c.fill===null?'—':c.fill+'<small style="font-size:23px">%</small>'}</strong></div><span class="badge ${s.key==='critical'?'red':s.key==='high'?'orange':'green'}">${s.label}</span></div><div class="detail-meta"><div><dt>Адрес площадки</dt><dd>${esc(c.address)}</dd></div><div><dt>Тип отходов</dt><dd>${esc(c.type)}</dd></div><div><dt>Вместимость</dt><dd>${num(c.capacity)} л</dd></div><div><dt>Уверенность оценки</dt><dd>${CONFIDENCE[c.confidence]}</dd></div><div><dt>Координаты${c.locationSource==='real'?'':' · пока выдуманные'}</dt><dd>${num(c.lat,4)}, ${num(c.lng,4)}</dd></div><div><dt>Источник</dt><dd>${c.source==='manual'?'Ручное наблюдение':c.source==='gemini'?'Фотоанализ Gemini':'Демонстрационные данные'}</dd></div></div><div class="detail-progress"><span style="width:${c.fill??0}%;background:${s.color}"></span></div><p>${c.explanation?esc(c.explanation):'Это демонстрационный контейнер. Добавьте собственное наблюдение, чтобы заменить исходную оценку.'}</p>${c.limitations?`<p style="margin-top:10px;font-size:9px">${esc(c.limitations)}</p>`:''}<div class="methodology" style="font-size:9px;padding:12px;margin-top:18px">Оценка по фото не измеряет физический объём. Уверенность качественная, не калиброванная вероятность. Порог приоритета вывоза: 75%; срочного вывоза: 90%.</div>`,`<button class="button" data-action="close-modal">Закрыть</button><button class="button primary" data-action="observation" data-id="${c.id}">${icon('camera')}Добавить наблюдение</button>`);}
let selectedFile=null,photoResult=null,observationTab='manual';
function showObservation(id='',tab='manual'){
 id=id||state.containers[0]?.id||'';
 selectedFile=null;photoResult=null;observationTab=tab;
 modal('Увидеть. Оценить. Позаботиться.',`<p style="margin-bottom:18px">Новое наблюдение для контейнера в вашем квартале.</p><div class="observation-tabs"><button class="${tab==='manual'?'active':''}" data-observation-tab="manual">${icon('bin')} Ручная оценка</button><button class="${tab==='photo'?'active':''}" data-observation-tab="photo">${icon('camera')} Анализ фотографии</button></div><form id="observation-form"><div class="field"><label for="observation-container">Контейнер</label><select id="observation-container" name="container">${state.containers.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div>${tab==='manual'?`<div class="field"><label for="manual-fill">Заполненность <strong id="manual-fill-value">${state.containers.find(c=>c.id===id)?.fill??50}%</strong></label><input type="range" id="manual-fill" name="fill" min="0" max="100" step="1" value="${state.containers.find(c=>c.id===id)?.fill??50}"><small>Визуальная приблизительная оценка наблюдателя.</small></div><div class="field"><label for="manual-confidence">Уверенность наблюдателя</label><select id="manual-confidence" name="confidence"><option value="medium">Средняя</option><option value="high">Высокая</option><option value="low">Низкая</option></select></div><div class="field"><label for="observation-note">Комментарий <span style="color:#a8b49b;font-weight:400">· необязательно</span></label><textarea id="observation-note" name="note" rows="2" maxlength="600" placeholder="Например, крышка открыта, содержимое хорошо видно"></textarea></div>`:`<label class="dropzone" id="dropzone">${icon('upload')}<strong>Перетащите фото или выберите файл</strong><small>JPEG, PNG или WebP · до 10 МБ<br>Содержимое контейнера должно быть видно</small><input id="photo-file" name="image" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Фотография контейнера"></label><p style="font-size:9px">При анализе фото передаётся в Gemini. Изображение не сохраняется на сервере приложения.</p><div id="photo-result"></div>${!state.analysisAvailable?'<div class="error-note">Для AI-анализа нужен сервер с настроенным ключом Gemini. Ручная оценка уже работает. Статус подключения доступен в настройках.</div>':''}`}<div id="observation-error" role="alert"></div></form>`,`<button class="button" data-action="close-modal">Отмена</button>${tab==='photo'?`<button class="button primary" id="analyze-button" data-action="analyze-photo" ${state.analysisAvailable?'':'disabled'}>${icon('sparkles')}Анализировать</button><button class="button primary" id="save-photo-button" data-action="save-photo" hidden>${icon('check')}Сохранить</button>`:`<button class="button primary" data-action="save-observation">${icon('check')}Сохранить наблюдение</button>`}`);
 const zone=$('#dropzone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');setPhoto(e.dataTransfer.files[0]);});}
}
function setPhoto(file){if(!file)return;photoResult=null;selectedFile=null;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){$('#photo-result').innerHTML='<div class="error-note">Выберите JPEG, PNG или WebP размером до 10 МБ.</div>';return;}selectedFile=file;const reader=new FileReader();reader.onload=()=>{if(!$('#dropzone'))return;$('#dropzone').innerHTML=`<img class="image-preview" src="${reader.result}" alt="Выбранная фотография контейнера"><small>${esc(file.name)} · ${num(file.size/1024)} КБ · нажмите, чтобы заменить</small><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Заменить фотографию">`;};reader.readAsDataURL(file);$('#photo-result').innerHTML='';$('#save-photo-button').hidden=true;$('#analyze-button').hidden=false;}
async function analyzePhoto(){if(!selectedFile){$('#photo-result').innerHTML='<div class="error-note">Сначала выберите фотографию.</div>';return;}const button=$('#analyze-button');button.disabled=true;button.innerHTML=icon('refresh','spin')+' Анализируем…';const file=selectedFile;try{const c=state.containers.find(x=>x.id===$('#observation-container').value),form=new FormData();form.set('image',file);form.set('latitude',c.lat);form.set('longitude',c.lng);const response=await fetch((state.settings.apiBase||'')+'/analyze',{method:'POST',headers:{Accept:'application/json'},body:form,signal:AbortSignal.timeout(70000)});const type=response.headers.get('content-type')??'';if(!type.includes('application/json'))throw new Error('Сервис анализа ещё не подключён. Настройте GEMINI_API_KEY на сервере или укажите адрес FastAPI в настройках.');const result=await response.json();if(!response.ok)throw new Error(result.error||'Не удалось проанализировать фотографию.');if(!$('#photo-result'))return;photoResult=result;$('#photo-result').innerHTML=`<div class="success-note"><strong>${result.fill_percentage===null?'Заполненность не определена':'Оценка: ~'+result.fill_percentage+'%'}</strong><br>Уверенность: ${esc(CONFIDENCE[result.confidence]??'не указана')}<br>${esc(result.explanation)}<br><small>${esc(result.limitations)}</small></div>`;$('#save-photo-button').hidden=false;button.hidden=true;}catch(e){if($('#photo-result'))$('#photo-result').innerHTML=`<div class="error-note">${esc(e.name==='TimeoutError'?'Сервис не ответил вовремя. Повторите позже.':e.message)}</div>`;}finally{button.disabled=false;button.innerHTML=icon('sparkles')+' Анализировать';}}
function saveObservation(fromPhoto=false){const id=$('#observation-container').value,c=state.containers.find(x=>x.id===id);if(!c)return;if(fromPhoto&&!photoResult)return;const data=fromPhoto?{fill:photoResult.fill_percentage,confidence:photoResult.confidence,explanation:photoResult.explanation,limitations:photoResult.limitations,source:'gemini'}:{fill:Number($('#manual-fill').value),confidence:$('#manual-confidence').value,explanation:$('#observation-note').value||'Ручная визуальная оценка наблюдателя.',limitations:'Приблизительная оценка, не инструментальный замер.',source:'manual'};Object.assign(c,data,{observedAt:new Date().toISOString()});persist();closeModal();render({keepScroll:true});toast('Наблюдение сохранено. Приоритеты и маршрут обновлены.');}
function about(){modal('Город, который становится внимательнее.',`<p>EcoMind AI помогает управляющей компании связать наблюдения за контейнерами с планированием вывоза. Основа проекта — ваш документ «Хакатон: идея 2.0» и его финальный план пилота.</p><h3>Что уже можно попробовать</h3><p>Настоящая карта Астаны с 3D-зданиями, реестр контейнеров, ручные наблюдения, анализ фотографии при подключённом Gemini, отбор остановок, оптимизация их порядка и сравнение по матрице 3 × 2.</p><h3>Что означают данные</h3><p>Площадки и заполненность изначально демонстрационные. Наблюдения сохраняются в браузере. Воздух — модельные данные CAMS через Open-Meteo. Нет локальных датчиков, обученной модели роста отходов или доказанного эффекта на воздух.</p><h3>Источники и инструменты</h3><p><a href="https://open-meteo.com/en/docs/air-quality-api" target="_blank" rel="noopener">Open-Meteo / Copernicus CAMS</a> — воздух и модельный прогноз.<br><a href="https://openfreemap.org/" target="_blank" rel="noopener">OpenFreeMap / OpenStreetMap</a> — географическая карта.<br><a href="https://maplibre.org/" target="_blank" rel="noopener">MapLibre GL JS</a> — отображение карты.<br>Маршрут — ближайший сосед и 2-opt, с расстояниями по прямой.</p><h3>Следующий шаг</h3><p>Согласовать пилот с ЖК и подрядчиком, собрать фото и GPS-треки за несколько недель и сравнить решения при одинаковом уровне обслуживания.</p>`,`<button class="button primary" data-action="close-modal">Начать знакомство ${icon('arrow-right')}</button>`,true);}
function download(filename,content,type='text/csv;charset=utf-8'){const blob=new Blob([type.startsWith('text/csv')?'\ufeff':'',content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл подготовлен и передан браузеру.');}
const csvValue=v=>{const s=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'":'')+s.replaceAll('"','""')+'"';};
function csv(rows){return rows.map(row=>row.map(csvValue).join(';')).join('\r\n');}
function exportData(){download('ecomind-observations.csv',csv([['ID','Название','Адрес','Широта','Долгота','Заполненность %','Уверенность','Источник','Время наблюдения','Комментарий'],...state.containers.map(c=>[c.id,c.name,c.address,c.lat,c.lng,c.fill,c.confidence,c.source||'demo',c.observedAt||'',c.explanation||'Демонстрационные данные'])]));}
function exportRoute(){const r=currentRoute();download('ecomind-route.csv',csv([['СХЕМАТИЧЕСКИЙ ПЛАН — НЕ ДОРОЖНАЯ НАВИГАЦИЯ'],['Метод','Ближайший сосед + 2-opt; расстояния по прямой'],['Политика отбора',state.route.policy],['Порог %',state.route.threshold],['Поправка к расстоянию',state.settings.factor],['Расчётная длина км',r.distance*state.settings.factor],['Порядок','ID','Название','Широта','Долгота','Заполненность %'],...r.points.map((c,i)=>[i,c.id,c.name,c.lat,c.lng,c.fill])]));}
function exportSimulation(){download('ecomind-simulation.csv',csv([['СИМУЛЯЦИЯ — НЕ ПОЛЕВЫЕ РЕЗУЛЬТАТЫ'],['Поправка',state.settings.factor],['Политика','Остановки','Базовый км','Оптимизированный км','Изменение %'],...['calendar','current','forecast'].map(p=>{const stops=selectStops(state.containers,p,state.route.threshold,24),r=optimizeRoute(stops);return [p,stops.length,r.originalDistance*state.settings.factor,r.distance*state.settings.factor,r.saving];})]));}
async function fetchAir(){
 if(state.airLoading)return;state.airLoading=true;state.airError='';if(['overview','air','containers'].includes(state.page))render({keepScroll:true});
 const lat=state.settings.latitude,lng=state.settings.longitude;
 try{const q=new URLSearchParams({latitude:lat,longitude:lng,current:'pm2_5,pm10,european_aqi,us_aqi',hourly:'european_aqi',timezone:'auto',forecast_days:'2'}),response=await fetch('https://air-quality-api.open-meteo.com/v1/air-quality?'+q,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error('Источник воздуха временно недоступен. Попробуйте обновить данные позже.');const payload=await response.json();if(payload.error||!payload.current)throw new Error('Источник не вернул текущие данные для этих координат.');const clean=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0?v:null;const current={...payload.current};['pm2_5','pm10','european_aqi','us_aqi'].forEach(k=>current[k]=clean(current[k]));const t=payload.current.time,chart=(payload.hourly?.time??[]).map((time,i)=>({time,value:clean(payload.hourly.european_aqi?.[i])})).filter(d=>d.time>=t&&d.value!==null).slice(0,24);state.air={current,chart,timezone:payload.timezone,fetchedAt:new Date().toISOString()};
 }catch(e){state.air=null;state.airError=e.name==='TimeoutError'?'Open-Meteo не ответил вовремя. Попробуйте ещё раз.':e.message||'Не удалось получить данные воздуха.';}
 finally{state.airLoading=false;if(['overview','air','containers'].includes(state.page)&&!$('#modal-root').innerHTML)render({keepScroll:true});}
}
async function checkApi(showToast=false){if(location.hostname.endsWith('github.io')&&!state.settings.apiBase){state.analysisAvailable=false;if(showToast)toast('Фотоанализ пока не подключён. Ручные наблюдения доступны.','info');return;}try{const r=await fetch((state.settings.apiBase||'')+'/api/health',{signal:AbortSignal.timeout(8000)});if(r.headers.get('content-type')?.includes('application/json')&&r.ok){const d=await r.json();state.analysisAvailable=Boolean(d.gemini_configured);}else state.analysisAvailable=false;}catch{state.analysisAvailable=false;}if(showToast){if(state.page==='settings')render({keepScroll:true});toast(state.analysisAvailable?'Gemini подключён и готов к запросам.':'Сервис Gemini ещё не настроен. Ручные наблюдения доступны.',state.analysisAvailable?'check':'info');}}
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
 const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render({keepScroll:true});return;}
 const tab=e.target.closest('[data-observation-tab]');if(tab){const id=$('#observation-container')?.value;showObservation(id,tab.dataset.observationTab);return;}
 const container=e.target.closest('[data-container]');if(container&&!e.target.closest('.map-viewport')){showContainer(container.dataset.container);return;}
 const button=e.target.closest('[data-action]');if(!button)return;
 switch(button.dataset.action){
 case 'observation':showObservation(button.dataset.id||'');break;
 case 'close-modal':closeModal();break;
 case 'save-observation':saveObservation();break;
 case 'analyze-photo':await analyzePhoto();break;
 case 'save-photo':saveObservation(true);break;
 case 'export':exportData();break;
 case 'export-route':exportRoute();break;
 case 'export-simulation':exportSimulation();break;
 case 'about':case 'methodology':about();break;
 case 'menu':$('#sidebar').classList.toggle('open');if(!$('.mobile-backdrop')){const el=document.createElement('div');el.className='mobile-backdrop';document.body.append(el);el.onclick=()=>{$('#sidebar').classList.remove('open');el.classList.remove('open');};}$('.mobile-backdrop').classList.toggle('open');break;
 case 'workspace':modal('Ваш пилотный квартал',`<div style="display:flex;gap:14px;align-items:center;margin-bottom:18px"><span class="connected-icon">${icon('building')}</span><div><h3 style="margin:0;font-size:14px">${esc(state.settings.name)}</h3><p style="font-size:10px">${esc(state.settings.city)}</p></div></div><p>В прототипе доступно одно пространство. Название и параметры можно изменить в настройках. Контейнеры демонстрируют сценарий для одного ЖК.</p>`,`<a class="button primary" href="#settings" data-action="close-modal">Перейти к настройкам ${icon('arrow-right')}</a>`);break;
 case 'profile':modal('Команда EcoMind',`<p>Локальное пространство пилота. В этой версии наблюдения доступны только в вашем браузере.</p><div class="methodology">Аккаунты команды и общая база наблюдений — следующий этап после подготовки полевого пилота.</div>`,`<button class="button primary" data-action="close-modal">Понятно</button>`);break;
 case 'notifications':modal('Сигналы вашего квартала',`<p style="font-size:9px;margin-bottom:8px">События рассчитаны по текущему набору. Исходные данные демонстрационные.</p>${state.containers.filter(c=>c.fill>=75).map(c=>`<button class="notice-item" style="width:100%;text-align:left" data-container="${c.id}"><span class="stat-icon">${icon(c.fill>=90?'warning':'bin')}</span><span><strong>${esc(c.name)} · ${c.fill}%</strong><p>${c.fill>=90?'Рекомендуется срочный вывоз':'Добавьте в план ближайшего рейса'}.</p><small>${esc(c.id)} · ${c.source?'Новое наблюдение':'Демонстрационная оценка'}</small></span></button>`).join('')||'<p>Нет контейнеров выше порога внимания.</p>'}`,`<a class="button primary" href="#routes" data-action="close-modal">Спланировать рейс ${icon('arrow-right')}</a>`);break;
 case 'calculate-route':render({keepScroll:true});toast('Порядок остановок пересчитан для выбранных контейнеров.');break;
 case 'refresh-air':await fetchAir();break;
 case 'check-api':await checkApi(true);break;
 case 'reset':modal('Начать демонстрацию заново?',`<p>Ваши наблюдения будут заменены исходным набором из 12 контейнеров. Сначала можно скачать CSV. Настройки пространства сохранятся.</p>`,`<button class="button" data-action="export">${icon('download')}Скачать CSV</button><button class="button" data-action="close-modal">Отмена</button><button class="button primary" data-action="confirm-reset">Сбросить</button>`);break;
 case 'confirm-reset':state.containers=structuredClone(DEMO_CONTAINERS);persist();closeModal();render({keepScroll:true});toast('Демонстрационный набор восстановлен.');break;
 }
});
document.addEventListener('input',e=>{
 if(e.target.id==='container-search'){state.search=e.target.value;$('#container-rows').innerHTML=tableRows(state.page==='containers'?Infinity:5);const n=filteredContainers().length;$('#table-count').textContent=`Показано ${Math.min(n,state.page==='containers'?n:5)} из ${n} контейнеров`;}
 if(e.target.id==='manual-fill')$('#manual-fill-value').textContent=e.target.value+'%';
 if(e.target.id==='route-threshold')$('#threshold-value').textContent=e.target.value+'%';
});
document.addEventListener('change',e=>{
 if(e.target.id==='photo-file')setPhoto(e.target.files[0]);
 if(e.target.id==='route-policy'){state.route.policy=e.target.value;render({keepScroll:true});}
 if(e.target.id==='route-threshold'){state.route.threshold=Number(e.target.value);render({keepScroll:true});}
 if(e.target.id==='route-horizon'){state.route.horizon=Number(e.target.value);render({keepScroll:true});}
});
document.addEventListener('submit',async e=>{
 if(e.target.id==='observation-form'){e.preventDefault();if(observationTab==='manual')saveObservation();else await analyzePhoto();}
 if(e.target.id==='air-coordinates'){e.preventDefault();const lat=Number($('#air-lat').value),lng=Number($('#air-lng').value);if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){toast('Введите корректные координаты.','warning');return;}state.settings.latitude=lat;state.settings.longitude=lng;persist();await fetchAir();}
 if(e.target.id==='settings-form'){e.preventDefault();const data=new FormData(e.target),api=String(data.get('apiBase')||'').trim().replace(/\/+$/,'');if(api&&!api.startsWith('https://')&&!/^http:\/\/(localhost|127\.0\.0\.1)(:|$)/.test(api)){toast('Используйте HTTPS URL сервера.','warning');return;}Object.assign(state.settings,{name:data.get('name').trim(),city:data.get('city').trim(),factor:Number(data.get('factor')),stopMinutes:Number(data.get('stopMinutes')),apiBase:api});persist();render({keepScroll:true});await checkApi();toast('Настройки пространства сохранены.');}
});
navigate();fetchAir();checkApi();
